// Generate changelog.json and status.json from git log
const logOutput = $input.first().json.stdout;
const entries = logOutput.split('\n').filter(Boolean).map(line => {
  const parts = line.split('||');
  const hash = parts[0] || '';
  const date = parts[1] || '';
  const message = parts.slice(2).join('||');
  return { hash, date, message, author: 'MiastoX Team' };
});

const version = '1.0.1';
const statusData = {
  version: version,
  lastBuild: new Date().toISOString().split('T')[0],
  players: 0,
  gameUrl: 'https://www.roblox.com/games/PLACE_ID',
  sourceUrl: 'https://github.com/Dawju9/MiastoX',
  buildCommit: entries[0]?.hash || 'unknown',
  status: 'operational'
};

const changelogData = entries;

return [{
  json: {
    statusJson: JSON.stringify(statusData, null, 2),
    changelogJson: JSON.stringify(changelogData, null, 2),
    version: version,
    commit: entries[0]?.hash || 'unknown'
  }
}];

return [{
  json: {
    status: 'deployed',
    url: 'https://Dawju9.github.io/MiastoX',
    timestamp: new Date().toISOString(),
    version: $input.first().json.version
  }
}];
